CREATE OR REPLACE FUNCTION public.edu_dashboard() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR public.edu_school() IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF;
WITH visible AS (SELECT * FROM public.students WHERE school_id=public.edu_school() AND (public.edu_has_role('director') OR teacher_id=auth.uid())),
gs AS (SELECT course AS grupo,count(*) AS total,round(avg(attendance),1) AS asistencia,round(avg(grade),1) AS nota_media,round(avg(submissions),1) AS tareas_entregadas,round(avg(resource_usage),1) AS recursos FROM visible GROUP BY course),
daily AS (SELECT DISTINCT ON (h.student_id,(h.recorded_at AT TIME ZONE 'UTC')::date) h.student_id,(h.recorded_at AT TIME ZONE 'UTC')::date AS day,h.attendance,h.grade FROM public.metric_history h JOIN visible s ON s.id=h.student_id ORDER BY h.student_id,(h.recorded_at AT TIME ZONE 'UTC')::date,h.recorded_at DESC,h.id DESC),
trend AS (SELECT day::text,round(avg(attendance),1) AS attendance,round(avg(grade),1) AS grade FROM daily GROUP BY day ORDER BY day DESC LIMIT 30),
impact AS (SELECT CASE WHEN s.resource_usage>=50 THEN 'high' ELSE 'low' END AS usage,count(*) AS total,round(avg(s.attendance),1) AS attendance,round(avg(s.submissions),1) AS submissions,round(avg(s.grade),1) AS grade,round(avg(s.attendance-first_metric.attendance) FILTER (WHERE history_count.n>1),1) AS change FROM visible s JOIN LATERAL (SELECT attendance FROM public.metric_history WHERE student_id=s.id ORDER BY recorded_at,id LIMIT 1) first_metric ON true JOIN LATERAL (SELECT count(*) AS n FROM public.metric_history WHERE student_id=s.id) history_count ON true GROUP BY CASE WHEN s.resource_usage>=50 THEN 'high' ELSE 'low' END)
SELECT jsonb_build_object('total',count(*),'active',count(*) FILTER(WHERE enrollment_status='active'),'withdrawn',count(*) FILTER(WHERE enrollment_status='withdrawn'),'completed',count(*) FILTER(WHERE enrollment_status='completed'),'retention',CASE WHEN count(*)>0 THEN round(100.0*count(*) FILTER(WHERE enrollment_status<>'withdrawn')/count(*),1) ELSE NULL END,'attendance',round(avg(attendance),1),'grade',round(avg(grade),1),'submissions',round(avg(submissions),1),'resources',round(avg(resource_usage),1),'priority',count(*) FILTER(WHERE attendance<75 OR grade<5 OR submissions<60),'plans',(SELECT count(*) FROM public.intervention_plans WHERE school_id=public.edu_school() AND (public.edu_has_role('director') OR teacher_id=auth.uid())),'completedPlans',(SELECT count(*) FROM public.intervention_plans WHERE status='completado' AND school_id=public.edu_school() AND (public.edu_has_role('director') OR teacher_id=auth.uid())),'groups',coalesce((SELECT jsonb_agg(gs) FROM gs),'[]'::jsonb),'trend',coalesce((SELECT jsonb_agg(trend ORDER BY day) FROM trend),'[]'::jsonb),'impact',coalesce((SELECT jsonb_agg(impact) FROM impact),'[]'::jsonb)) INTO result FROM visible; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.edu_dashboard() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.edu_dashboard() TO authenticated;